import random
import string
from typing import List

# Generator for valid HDF5 object path strings to feed FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME
# Focus: object path strings used across many H5* by-name/by-idx stubs.
# Requirements from stubs:
# - Non-empty strings
# - Often treated as HDF5 paths; absolute paths should start with '/'
# - Names sanitized to avoid control chars and embedded NULs
# - Lengths often limited (<= 128/256), we keep under 256
# - Some calls expect simple relative names (e.g., group names), others absolute
# - External link builders also call FUZZ_PARAM_FILENAME; we avoid generating those here, only the path buffer
# - Return bytes buffer containing a plausible object path; fuzzer runtime will reuse as needed.

SAFE_CHARS = string.ascii_letters + string.digits + "_-"

def _rand_component(rng: random.Random, min_len: int = 1, max_len: int = 16) -> str:
    n = rng.randint(min_len, max_len)
    # Prefer readable short names, ensure not '.' or '..' unless explicitly requested
    comp = ''.join(rng.choice(SAFE_CHARS) for _ in range(n))
    # Avoid empty or reserved single dots here
    if comp in (".", "..", ""):
        comp = "g" + comp.replace('.', 'd')
    return comp

def _make_absolute_path(rng: random.Random) -> str:
    # Depth 1-4 components
    depth = rng.randint(1, 4)
    comps = [_rand_component(rng) for _ in range(depth)]
    # Occasionally include a common object type name to increase open success
    if rng.random() < 0.35:
        comps[-1] = rng.choice(["group", "dset", "data", "tbl", "attr", "link"]) + ("_" + comps[-1] if rng.random() < 0.5 else "")
    path = "/" + "/".join(comps)
    # Cap length defensively
    return path[:255]

def _make_relative_path(rng: random.Random) -> str:
    # Either '.' (current), simple name, or nested relative like 'g1/g2'
    mode = rng.random()
    if mode < 0.15:
        return "."
    depth = 1 if mode < 0.65 else rng.randint(2, 4)
    comps = [_rand_component(rng) for _ in range(depth)]
    return "/".join(comps)[:255]

def _maybe_attribute_like(rng: random.Random) -> str:
    # Some APIs need attribute names as separate FUZZ_PARAM_STR; these must be non-empty and simple
    # Provide a colon suffix sometimes to emulate naming patterns, but keep as valid object path segment
    base = _rand_component(rng, 3, 12)
    if rng.random() < 0.3:
        base += rng.choice(["_meta", "_info", "_attr", "_v1", "_v2"]) 
    return base

def _make_vds_source_path(rng: random.Random) -> str:
    # For virtual dataset source dataset name (second arg to H5Pset_virtual), usually absolute
    return _make_absolute_path(rng)

def _mix_paths(rng: random.Random) -> str:
    # Blend various path styles used across stubs
    choice = rng.random()
    if choice < 0.6:
        return _make_absolute_path(rng)
    elif choice < 0.85:
        return _make_relative_path(rng)
    else:
        # Occasionally an absolute with short depth to aid existence
        return "/" + _rand_component(rng)

def _ensure_ascii(s: str) -> str:
    # Map any unexpected characters to underscores (should not occur with SAFE_CHARS)
    out = []
    for ch in s:
        if ord(ch) < 0x20 or ch == '\x00':
            out.append('_')
        else:
            out.append(ch)
    return ''.join(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide scenario bucket matching common stub use cases
    scenario = rng.random()
    if scenario < 0.15:
        # Single component relative group/dataset name
        s = _make_relative_path(rng)
    elif scenario < 0.3:
        # Attribute-like simple name
        s = _maybe_attribute_like(rng)
    elif scenario < 0.45:
        # Short absolute path
        s = "/" + _rand_component(rng, 1, 12)
    elif scenario < 0.7:
        # Multi-component absolute path
        s = _make_absolute_path(rng)
    elif scenario < 0.85:
        # VDS source-like absolute dataset path
        s = _make_vds_source_path(rng)
    else:
        # Nested relative path
        s = _make_relative_path(rng)
    s = _ensure_ascii(s)
    if not s:
        s = "."
    # Length guard (most stubs cap at 128/256). Keep within 256.
    s = s[:255]
    return s.encode('utf-8')
